/* global process, console, URL */
/**
 * Single source of truth for the GenDragoon design tokens: tokens.json.
 * Generates src/theme.ts (React Native + TS) and src/tokens.css (DOM: desktop, web, extension).
 * `node scripts/build-tokens.mjs --check` fails when the generated files are stale.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = new URL("../", import.meta.url);
const tokens = JSON.parse(readFileSync(new URL("tokens.json", root), "utf8"));
const kebab = (k) => k.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`);
const vars = (p) => Object.entries(p).map(([k, v]) => `  --${kebab(k)}: ${v};`).join("\n");

const css = `/* GENERATED by scripts/build-tokens.mjs from tokens.json. Do not edit. */
/* Dark is the default. data-theme="light" forces light. data-theme="system" follows the OS. */
:root,
:root[data-theme="dark"],
:root[data-theme="system"] {
  color-scheme: dark;
${vars(tokens.palette.dark)}
  --dur-fast: ${tokens.motion.fast}ms;
  --dur-base: ${tokens.motion.base}ms;
  --dur-slow: ${tokens.motion.slow}ms;
  --ease-out: ${tokens.motion.easeOut};
  --ease-in-out: ${tokens.motion.easeInOut};
${Object.entries(tokens.space).map(([k, v]) => `  --space-${k}: ${v}px;`).join("\n")}
${Object.entries(tokens.radii).map(([k, v]) => `  --radius-${k}: ${v}px;`).join("\n")}
}

:root[data-theme="light"] {
  color-scheme: light;
${vars(tokens.palette.light)}
}

@media (prefers-color-scheme: light) {
  :root[data-theme="system"] {
    color-scheme: light;
${vars(tokens.palette.light).replace(/^ {2}/gm, "    ")}
  }
}

@media (prefers-reduced-motion: reduce) {
  :root { --dur-fast: 1ms; --dur-base: 1ms; --dur-slow: 1ms; }
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}
`;

const obj = (o) => JSON.stringify(o, null, 2);
const ts = `/**
 * GENERATED by scripts/build-tokens.mjs from tokens.json. Do not edit.
 * Platform-neutral tokens. DOM apps use tokens.css (same values). React Native imports this module.
 * \`colors\` is the dark palette (the default) so existing imports keep working.
 */

export const darkColors = ${obj(tokens.palette.dark)} as const;

export const lightColors: { readonly [K in keyof typeof darkColors]: string } = ${obj(tokens.palette.light)};

export type ThemeName = "dark" | "light";
export type ThemePreference = "dark" | "light" | "system";
export const DEFAULT_THEME_PREFERENCE: ThemePreference = "dark";

export const colors = darkColors;
export const themes = { dark: darkColors as { readonly [K in keyof typeof darkColors]: string }, light: lightColors } as const;

/** Resolve a stored preference to a concrete theme. \`system\` follows the OS; unknown values fall back to dark. */
export function resolveTheme(preference: string | null | undefined, systemPrefersLight: boolean): ThemeName {
  if (preference === "light") return "light";
  if (preference === "system") return systemPrefersLight ? "light" : "dark";
  return "dark";
}

export const space = ${obj(tokens.space)} as const;

export const radii = ${obj(tokens.radii)} as const;

/** Minimum tap target in points. */
export const tapTarget = ${tokens.tapTarget};

export const type = ${obj(tokens.type)} as const;

export const motion = ${obj(tokens.motion)} as const;

export const shadow = {
  card: {
    shadowColor: "#000000",
    shadowOffset: { width: 0, height: 18 },
    shadowOpacity: 0.28,
    shadowRadius: 40,
    elevation: 8,
  },
  button: {
    shadowColor: "#6d4aff",
    shadowOffset: { width: 0, height: 8 },
    shadowOpacity: 0.28,
    shadowRadius: 18,
    elevation: 4,
  },
} as const;

/** Relative-luminance contrast ratio for opaque #rrggbb colors (WCAG 2.x). */
export function contrastRatio(fg: string, bg: string): number {
  const lum = (hex: string) => {
    const n = hex.replace("#", "");
    const [r, g, b] = [0, 2, 4].map((i) => {
      const c = parseInt(n.slice(i, i + 2), 16) / 255;
      return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
    });
    return 0.2126 * r! + 0.7152 * g! + 0.0722 * b!;
  };
  const [a, b] = [lum(fg), lum(bg)].sort((x, y) => y - x);
  return (a! + 0.05) / (b! + 0.05);
}
`;

const targets = [["src/tokens.css", css], ["src/theme.ts", ts]];
const check = process.argv.includes("--check");
let stale = false;
for (const [file, content] of targets) {
  const path = fileURLToPath(new URL(file, root));
  if (check) {
    let current = "";
    try { current = readFileSync(path, "utf8"); } catch { /* missing */ }
    if (current !== content) { stale = true; console.error(`${file} is stale: run pnpm --filter @gendragoon/ui tokens`); }
  } else {
    writeFileSync(path, content);
  }
}
if (check && stale) process.exit(1);
